<?php require_once __DIR__.'/../includes/functions.php';role('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$c=(int)$_POST['course_id'];$st=(int)$_POST['student_id'];$s=$conn->prepare('INSERT IGNORE INTO enrollments(course_id,student_id) VALUES(?,?)');$s->bind_param('ii',$c,$st);$msg=$s->execute()?'Enrollment saved.':'Could not enroll student.';}$courses=$conn->query('SELECT id,title FROM courses ORDER BY title');$students=$conn->query("SELECT id,name,last_name,first_name,middle_name,name_extension,email FROM users WHERE role='student' AND is_active=1 ORDER BY last_name,first_name,name");$page_title='Enroll Students';include __DIR__.'/../includes/header.php';?><h1>Enroll Students</h1><div class="card"><?php if($msg):?><div class="alert info"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Course</label><select name="course_id" required><option value="">Select course</option><?php while($c=$courses->fetch_assoc()):?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endwhile;?></select><label>Student</label><select name="student_id" required><option value="">Select student</option><?php while($s=$students->fetch_assoc()):?><?php $student_name=$s['last_name']?trim($s['last_name'].', '.$s['first_name'].($s['middle_name']?' '.$s['middle_name']:'').($s['name_extension']?' '.$s['name_extension']:'')):$s['name'];?> <option value="<?=$s['id']?>"><?=e($student_name.' · '.$s['email'])?></option><?php endwhile;?></select><button class="btn">Enroll student</button></form></div><?php include __DIR__.'/../includes/footer.php';?>
